ard","_info":{"sla_href":"https://connect.verveit.com/v4_6_release/apis/3.0/service/SLAs/1"}},"slaStatus":"Plan by Mon 10/24 4:00 PM UTC-07","requestForChangeFlag":false,"currency":{"id":7,"symbol":"$","currencyCode":"USD","decimalSeparator":".","numberOfDecimals":2,"thousandsSeparator":",","negativeParenthesesFlag":true,"displaySymbolFlag":false,"currencyIdentifier":"USD","displayIdFlag":false,"rightAlign":false,"name":"US Dollars","_info":{"currency_href":"https://connect.verveit.com/v4_6_release/apis/3.0/finance/currencies/7"}},"_info":{"lastUpdated":"2022-10-22T00:16:40Z","updatedBy":"dbarnett","dateEntered":"2022-10-22T00:09:44Z","enteredBy":"dbarnett","activities_href":"https://connect.verveit.com/v4_6_release/apis/3.0/sales/activities?conditions=ticket/id=719332","scheduleentries_href":"https://connect.verveit.com/v4_6_release/apis/3.0/schedule/entries?conditions=type/id=4 AND objectId=719332","documents_href":"https://connect.verveit.com/v4_6_release/apis/3.0/system/documents?recordType=Ticket&recordId=719332","configurations_href":"https://connect.verveit.com/v4_6_release/apis/3.0/service/tickets/719332/configurations","tasks_href":"https://connect.verveit.com/v4_6_release/apis/3.0/service/tickets/719332/tasks","notes_href":"https://connect.verveit.com/v4_6_release/apis/3.0/service/tickets/719332/notes","products_href":"https://connect.verveit.com/v4_6_release/apis/3.0/procurement/products?conditions=ticket/id=719332","timeentries_href":"https://connect.verveit.com/v4_6_release/apis/3.0/time/entries?conditions=(chargeToType='ServiceTicket' OR chargeToType='ProjectTicket') AND chargeToId=719332","expenseEntries_href":"https://connect.verveit.com/v4_6_release/apis/3.0/expense/entries?conditions=(chargeToType='ServiceTicket' OR chargeToType='ProjectTicket') AND chargeToId=719332"},"escalationStartDateUTC":"2022-10-22T00:09:45Z","escalationLevel":5,"minutesBeforeWaiting":0,"respondedSkippedMinutes":0,"resplanSkippedMinutes":0,"respondedHours":10.0,"respondedBy":"dbarnett","resplanHours":10.0,"resolutionHours":40.0,"minutesWaiting":0,"customFields":[{"id":35,"caption":"Prevention","type":"Text","entryMethod":"List","numberOfDecimals":0,"value":"Not Selected","connectWiseId":"225cb83d-498c-ee11-82e2-000d3a313a77","rowNum":1,"userDefinedFieldRecId":35,"podId":"service_ticket_ticket"},{"id":36,"caption":"Prevention Recommendation","type":"TextArea","entryMethod":"EntryField","numberOfDecimals":0,"value":null,"connectWiseId":"235cb83d-498c-ee11-82e2-000d3a313a77","rowNum":2,"userDefinedFieldRecId":36,"podId":"service_ticket_ticket"}],"_notes":[{"id":1284324,"text":"There appears to be an issue with backup images of laptops taken with MDT. When trying to mount the image, it will produce the error \"The parameter is incorrect\" and only mount a couple folders from the image.","detailDescriptionFlag":true,"internalAnalysisFlag":false,"member":{"id":260,"identifier":"dbarnett","name":"Dan Barnett","_info":{"member_href":"https://connect.verveit.com/v4_6_release/apis/3.0/system/members/260","image_href":"https://connect.verveit.com/v4_6_release/apis/3.0/system/members/260/image?lm=2023-10-16T16:32:21Z"}},"dateCreated":"2022-10-22T00:09:44Z"}],"_time_entries":[{"id":344437,"_info":{"notes":"-Looked at a backup WIM taken from MDT and tried to mount\n-Reviewed DISM logs from failed mount and it appears it could be related to some issues processing one of the files within the image\n-Tried mounting with the 'optimize' switch, so it just mounts pointers and doesn't actually look at the contents too closely. It was also having issues with this.\n-Checked online to see if this is a common issue and was not finding any good info\n-Checked the details on the image and it lists its size as 128GB even though the actual amount of data within it is much less. I suspect that is because it is an image of the full disk so it grabbed all the data. \n-Tried exporting the image to a new WIM. It did not shrink the total reported size of the WIM at all and produced the same error when trying to mount it.\n-I was able to traverse the WIM with 7Zip though and could copy out data. It may not be worth the time to continue investigating this since it is a process that is rarely used.","time_href":"https://connect.verveit.com/v4_6_release/apis/3.0/time/entries/344437"}}],"_version":"2022-10-22T00:16:40Z"}
